PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?p / 100) AS ?m3) WHERE {
  { SELECT ?c (SUM(?o) AS ?oilC) WHERE {
      ?wp a energia:WellProduction ; energia:inConcession ?c ; energia:oil ?o .
    } GROUP BY ?c }
  { SELECT DISTINCT ?s ?c ?p WHERE {
      ?s a energia:Stake ; energia:inConcession ?c ; energia:partner ?e ; energia:percent ?p .
      ?e energia:name ?n .
      FILTER(STRSTARTS(UCASE(STR(?n)), "YPF"))
    } }
}
